// Generate a design sheet from the production palette and bar geometry.
#include "tank_visual.hpp"
#include <iostream>
#include <iomanip>
int main(){using namespace visual::tank;std::cout<<"<svg xmlns='http://www.w3.org/2000/svg' width='1440' height='760' viewBox='0 0 1440 760'><rect width='1440' height='760' fill='#080f17'/><g font-family='Noto Sans CJK SC,Microsoft YaHei,sans-serif'><text x='32' y='45' fill='#e7eff7' font-size='25'>Tank / 朝向 · 范围 · 计时条</text><text x='32' y='74' fill='#8398ac' font-size='14'>三套样式，同一套布局计算。右侧竖条为另一种可选方向示意。</text>";
 for(unsigned p=0;p<3;++p){float left=24+p*472;Point c{left+220,355};auto color=palette(p);std::cout<<"<rect x='"<<left<<"' y='100' width='448' height='625' rx='16' fill='#101c29' stroke='#26384b'/><text x='"<<left+22<<"' y='145' fill='#e7eff7' font-size='23'>"<<visualName(p)<<"</text><text x='"<<left+22<<"' y='171' fill='#8ea4b8' font-size='13'>"<<(p==0?"CYAN / GOLD":p==1?"AMBER / TACTICAL":"ICE / MINT")<<"</text>";
  for(int i=-3;i<=3;++i){float d=i*45;std::cout<<"<path d='M "<<c.x+d<<" 200 V 525 M "<<left+34<<' '<<c.y+d<<" H "<<left+414<<"' stroke='#1b2c3e'/>";}
  VisualSettings s;s.preset=p;std::vector<Segment> lines;demoRange(lines,c,1.15f,p);barGeometry(lines,barCenter(c,s,1),s,1,.68f);s.vertical=true;s.x=135;s.y=0;barGeometry(lines,barCenter(c,s,1),s,1,.68f);
  for(const auto& l:lines){std::cout<<"<line x1='"<<l.a.x<<"' y1='"<<l.a.y<<"' x2='"<<l.b.x<<"' y2='"<<l.b.y<<"' stroke='#"<<std::hex<<std::setw(6)<<std::setfill('0')<<(l.color&0xffffff)<<std::dec<<"' stroke-width='"<<l.width<<"'/>";}
  std::cout<<"<circle cx='"<<c.x<<"' cy='"<<c.y-38<<"' r='12' fill='#dfeaf3'/><rect x='"<<c.x-24<<"' y='"<<c.y-23<<"' width='48' height='51' rx='6' fill='#96adbe'/><path d='M "<<c.x-34<<' '<<c.y-7<<" H "<<c.x+34<<" M "<<c.x-10<<' '<<c.y+28<<" l -6 32 M "<<c.x+10<<' '<<c.y+28<<" l 6 32' stroke='#c1d2df' stroke-width='6' stroke-linecap='round'/><circle cx='"<<c.x<<"' cy='"<<c.y<<"' r='3' fill='#ffffff'/><text x='"<<c.x-20<<"' y='"<<c.y+82<<"' fill='#dfeaf3' font-size='13'>TANK</text><text x='"<<left+22<<"' y='594' fill='#d5e3ef' font-size='15'>横条 / 竖条 · 位置 / 长度 / 厚度</text><text x='"<<left+22<<"' y='624' fill='#8ea4b8' font-size='14'>方向键移动，- / = 精调选中参数</text><rect x='"<<left+22<<"' y='656' width='120' height='36' rx='8' fill='#203448'/><text x='"<<left+43<<"' y='680' fill='#dceaf6' font-size='14'>保存设置</text>";(void)color;
 }std::cout<<"</g></svg>\n";
}
